// The rep brief is extractive: the prospect's own words, quoted, plus facts inserted by code from the registry and, when
// the organization has a rate group, from the rate file (src/outbound/fact.ts). Nothing in here is generated by a model.
import type { DealSignals } from './enterprise';
import type { LeadEvent, Normalized, Qualification, Resolution, Source } from './schema';

const METHOD_TEXT: Record<string, string> = {
  curated_domain: 'matched on domain (curated list)', org_domain: 'matched on domain', company_name: 'matched on company name',
  site_title: 'matched on homepage title', nppes: 'matched in NPPES', tld: 'placed by domain ending', inferred: 'inferred from title', crm: 'matched to an account already in the CRM',
  person: 'chosen by a person in review', none: 'not matched',
};

export function orgFacts(res: Resolution): string {
  const f = res.firmographics;
  const bits: string[] = [];
  if (res.accountId?.startsWith('ahrq:')) {
    bits.push('AHRQ health system');
    if (f.hospitals) bits.push(`${f.hospitals} hospitals`);
    if (f.beds) bits.push(`${f.beds.toLocaleString('en-US')} beds`);
    if (f.states?.length) bits.push(f.states.length > 3 ? `${f.states.length} states` : f.states.join('/'));
  } else if (res.accountId?.startsWith('ccn:')) {
    bits.push('standalone hospital (CMS)');
    if (f.cmsType) bits.push(f.cmsType);
    if (f.beds) bits.push(`${f.beds} beds`);
  } else if (res.accountId?.startsWith('payer:')) {
    bits.push(`payer${f.payerKind ? ' (' + f.payerKind + ')' : ''}`);
  } else if (res.accountId?.startsWith('npi:')) {
    bits.push(`provider group, NPI ${f.npi}`);
    if (f.taxonomy) bits.push(f.taxonomy);
  } else if (res.segment !== 'unknown_org') {
    bits.push(res.subsegment ? `${res.segment.replace(/_/g, ' ')}, ${res.subsegment}` : res.segment.replace(/_/g, ' '));
  } else bits.push('organization not identified');
  bits.push(METHOD_TEXT[res.method] ?? res.method);
  return bits.join(', ');
}

/** Prospect-supplied context that is not a free-text message: guide, badge notes, usage. All facts, no prose. */
export function contextFacts(ev: LeadEvent): string | null {
  const c = ev.context as Record<string, any>;
  if (ev.source === 'sample_signup') return `${c.sessions ?? 0} session(s), ${c.searches ?? 0} search(es)${c.markets?.length ? ', markets: ' + c.markets.join(', ') : ''}`;
  if (ev.source === 'guide_download' && c.guide) return `downloaded "${c.guide}"`;
  if (ev.source === 'event_scan' && c.event) return `badge scan at ${c.event}`;
  if (ev.source === 'marketplace' && c.marketplace) return `${c.marketplace} listing inquiry`;
  if (ev.source === 'api_key' && c.product) return `created a ${c.product} developer key`;
  if (ev.source === 'web_intent') return `${(c.visits ?? []).length} page view(s), ${c.visitors ?? '?'} visitor(s)`;
  return null;
}

export function quoteOf(n: Normalized, max = 220): string | null {
  if (!n.message) return null;
  const m = n.message.replace(/\s+/g, ' ');
  return m.length > max ? m.slice(0, max - 1).trimEnd() + '…' : m;
}

/** Lines of fact about the account and the deal, each null when there is nothing to say (decisions 25 and 26). */
export interface BriefLines {
  /** "Enterprise: 145 hospitals in 20 states", with the deal-size cues quoted; "Deal size: ..." for cues at an account that is not enterprise */
  enterprise: string | null;
  /** "Also in from this account: ..." other people at the account in the last 30 days */
  alsoIn: string | null;
  /** "Referral: Wrenfield Health, a customer owned by Avery (...)" */
  referral: string | null;
}

export const NO_LINES: BriefLines = { enterprise: null, alsoIn: null, referral: null };

export interface Brief extends BriefLines {
  person: string; org: string; whyNow: string; quote: string | null;
  /** the organization's own rate from the rate file, one line, or null */
  rates: string | null;
  text: string;
}

/**
 * The Enterprise line: the account's fact line when it is enterprise, and the deal-size cues quoted from the message. A lead
 * with cues at an account that is not enterprise gets a Deal size line with the cues alone; a lead with neither gets no line.
 */
export function enterpriseLine(deal: DealSignals): string | null {
  const quoted = deal.cues.map(c => `"${c.phrase}"`).join(', ');
  if (deal.enterprise.enterprise) return `Enterprise: ${deal.enterprise.fact ?? 'enterprise account'}${quoted ? `; deal-size cues ${quoted}` : ''}`;
  return quoted ? `Deal size: ${quoted}` : null;
}

/** Each door in a few plain words, as a brief or a note names it. */
export const DOOR_TEXT: Record<Source, string> = {
  calendly_demo: 'demo request', guide_download: 'guide download', signal_ask_waitlist: 'Signal Ask waitlist', sample_signup: 'sample signup',
  marketplace: 'marketplace inquiry', api_key: 'API key', event_scan: 'badge scan', web_intent: 'web visits',
};

/** "6 hours ago", from one ISO time to another. */
export function agoText(thenIso: string, nowIso: string): string {
  const min = Math.max(0, Math.round((Date.parse(nowIso) - Date.parse(thenIso)) / 60_000));
  if (min < 60) return `${min} minute${min === 1 ? '' : 's'} ago`;
  const h = Math.round(min / 60);
  if (h < 48) return `${h} hour${h === 1 ? '' : 's'} ago`;
  const d = Math.round(h / 24);
  return `${d} days ago`;
}

/** One other person at the account, as the brief lists them. */
export interface AccountContact { name: string; title: string | null; source: Source; receivedAt: string }

/** Contacts listed by name; the rest are counted. */
export const ALSO_IN_LISTED = 3;

/** "Also in from this account: Helena Marsh, SVP, Managed Care (demo request, 6 hours ago); and 2 more", or null when nobody else is in. */
export function alsoInLine(contacts: readonly AccountContact[], nowIso: string): string | null {
  if (!contacts.length) return null;
  const listed = contacts.slice(0, ALSO_IN_LISTED).map(c => `${c.name}${c.title ? `, ${c.title}` : ''} (${DOOR_TEXT[c.source]}, ${agoText(c.receivedAt, nowIso)})`);
  const more = contacts.length - ALSO_IN_LISTED;
  return `Also in from this account: ${listed.join('; ')}${more > 0 ? `; and ${more} more` : ''}`;
}

export function buildBrief(ev: LeadEvent, n: Normalized, res: Resolution, qual: Qualification, rates: string | null = null, lines: BriefLines = NO_LINES): Brief {
  const person = [n.firstName, n.lastName].filter(Boolean).join(' ') || n.email || 'Account-level signal';
  const title = n.title ? `${person}, ${n.title}` : person;
  const org = `${res.accountName ?? n.companyRaw ?? 'Unknown organization'}: ${orgFacts(res)}`;
  const quote = quoteOf(n);
  const ctxFacts = contextFacts(ev);
  const e = qual.rules.evidence;
  const timing = qual.final.sources?.urgency === 'rules' && e?.urgencyCue ? ` ("${e.urgencyCue}"${e.urgencyDate ? `, ${e.urgencyDate}, ${e.urgencyDays} days out` : ''})` : '';
  const whyNow = `${ev.source.replace(/_/g, ' ')}; urgency ${qual.final.urgency.replace(/_/g, ' ')}${timing}; use case ${qual.final.useCase.replace(/_/g, ' ')}`;
  const said = quote ? `They wrote: "${quote}"` : (ctxFacts ? `Activity: ${ctxFacts}` : 'No message.');
  const facts = [lines.enterprise, rates, lines.referral, lines.alsoIn].filter((x): x is string => !!x);
  const text = [title, org, ...facts, `Why now: ${whyNow}`, said].join('\n');
  return { person: title, org, whyNow, quote, rates, ...lines, text };
}
